export interface Product {
  pictures(pictures: any): unknown;
  categoryId: number;
  productId: number;
  productName: string;
  detail: string;
  price: number;
  weight: number;
  totalStock: number;
  categoryName: string;
  productPictures: { productPictureUrl: string; position: number }[] | null;
  status: ProductStatus;
}

export enum ProductStatus {
  DRAFT = "DRAFT",
  ACTIVE = "ACTIVE",
}

export interface Category {
  categoryId: number;
  categoryName: string;
  categoryPicture: string;
}

export interface ProductFormValues {
  productName: string;
  detail: string;
  price: number;
  weight: number;
  productCategory: string;
  productPictures: (string | null)[];
}